-- ============================================
-- LUMA — Thème 13 : LONG 2/3 x4 — Négocier un partenariat lors de l'événement
-- ============================================


update scenarios set content = '{"characters": {"exec": "le dirigeant"}, "start_node": "n1", "nodes": {"n1": {"speaker": "exec", "text": "So, I''ve heard great things about your company''s approach to customer engagement.", "text_fr": "Alors, j''ai entendu de bonnes choses sur l''approche de votre entreprise envers l''engagement client.", "choices": [{"text": "Thank you, we''ve put a lot of thought into that. What''s caught your interest specifically?", "text_fr": "Merci, on a beaucoup réfléchi à ça. Qu''est-ce qui a attiré votre attention en particulier ?", "next": "n2"}, {"text": "That''s kind of you to say. Are you exploring similar strategies for your company?", "text_fr": "C''est gentil de dire ça. Vous explorez des stratégies similaires pour votre entreprise ?", "next": "n2b"}]}, "n2": {"speaker": "exec", "text": "Your retention strategies, mainly. We''ve struggled with that exact challenge.", "text_fr": "Vos stratégies de rétention, principalement. On a eu du mal avec exactement ce défi.", "choices": [{"text": "Interesting — our approaches might actually complement each other quite well.", "text_fr": "Intéressant — nos approches pourraient en fait bien se compléter.", "next": "n3"}]}, "n2b": {"speaker": "exec", "text": "We are, actually, though we haven''t found the right approach yet.", "text_fr": "On l''est, en fait, même si on a pas encore trouvé la bonne approche.", "choices": [{"text": "We might be able to help with that, or at least share some insights.", "text_fr": "On pourrait peut-être aider avec ça, ou au moins partager quelques idées.", "next": "n3"}]}, "n3": {"speaker": "exec", "text": "I''d genuinely be interested in exploring that. What would a potential partnership look like?", "text_fr": "Je serais vraiment intéressé d''explorer ça. À quoi ressemblerait un partenariat potentiel ?", "choices": [{"text": "Perhaps we could pilot a joint program, testing our combined approach with a smaller client base first.", "text_fr": "Peut-être qu''on pourrait piloter un programme conjoint, en testant notre approche combinée avec une clientèle plus petite d''abord.", "next": "n4"}, {"text": "We could start with a knowledge-sharing agreement before considering anything more formal.", "text_fr": "On pourrait commencer par un accord de partage de connaissances avant de considérer quelque chose de plus formel.", "next": "n4"}]}, "n4": {"speaker": "exec", "text": "A pilot program is appealing — lower risk while we assess real compatibility.", "text_fr": "Un programme pilote est attrayant — moins de risque pendant qu''on évalue la vraie compatibilité.", "choices": [{"text": "Exactly my thinking. We could define clear success metrics from the start.", "text_fr": "Exactement ma pensée. On pourrait définir des indicateurs de réussite clairs dès le départ.", "next": "n5"}]}, "n5": {"speaker": "exec", "text": "I like that structured approach. What timeline were you imagining for this pilot?", "text_fr": "J''aime cette approche structurée. Vous imaginiez quel calendrier pour ce pilote ?", "choices": [{"text": "Perhaps a three-month trial, with a formal review at the end to decide next steps.", "text_fr": "Peut-être un essai de trois mois, avec une révision formelle à la fin pour décider des prochaines étapes.", "next": "n6"}, {"text": "I''d suggest starting smaller — maybe six weeks, to get quick, actionable data.", "text_fr": "Je suggérerais de commencer plus petit — peut-être six semaines, pour avoir des données rapides et exploitables.", "next": "n6"}]}, "n6": {"speaker": "exec", "text": "That works well for us. Though I should mention — we''d need buy-in from our board first.", "text_fr": "Ça nous convient bien. Même si je devrais mentionner — on aurait besoin de l''accord de notre conseil d''abord.", "choices": [{"text": "That''s completely understandable. What information would help make that case internally?", "text_fr": "C''est totalement compréhensible. Quelles informations aideraient à défendre ça en interne ?", "next": "n7"}]}, "n7": {"speaker": "exec", "text": "A clear one-pager outlining expected outcomes and resource commitments would help a lot.", "text_fr": "Une page claire décrivant les résultats attendus et les engagements de ressources aiderait beaucoup.", "choices": [{"text": "I can put that together and send it over by end of week.", "text_fr": "Je peux préparer ça et vous l''envoyer d''ici la fin de la semaine.", "next": "n8"}]}, "n8": {"speaker": "exec", "text": "That would be excellent. This conversation has genuinely exceeded my expectations for today.", "text_fr": "Ce serait excellent. Cette conversation a vraiment dépassé mes attentes pour aujourd''hui.", "choices": [{"text": "Likewise — I think this could be the start of something really valuable for both companies.", "text_fr": "Pareillement — je pense que ça pourrait être le début de quelque chose de vraiment précieux pour les deux entreprises.", "next": "n9"}]}, "n9": {"speaker": "exec", "text": "Agreed. Let''s make sure we follow through properly on both sides.", "text_fr": "D''accord. Assurons-nous de bien donner suite des deux côtés.", "choices": [{"text": "Absolutely, I''ll have that document to you by Friday, without fail.", "text_fr": "Absolument, je vous aurai ce document d''ici vendredi, sans faute.", "next": "end_partnership"}]}, "end_partnership": {"speaker": "exec", "text": "I''m looking forward to it. This might just be the most valuable conversation I''ve had at this conference.", "text_fr": "J''ai hâte. Ça pourrait bien être la conversation la plus précieuse que j''ai eue à cette conférence.", "end": true, "ending_label": "Partenariat informel négocié avec succès 🤝📈"}}}'::jsonb, is_playable = true
where title = 'Négocier un partenariat lors de l''''événement'
  and theme_id = (select id from scenario_themes where position = 13 and language_id = (select id from languages where code = 'en'));
